      "id": "modern-c05-l22-p02-012",
      "title": "1969年から戦略兵器制限交渉",
      "body": [
        "そして1969年、米ソ両国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦略兵器制限交渉</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SALT<rt>ソルト</rt></ruby></strong></span>】</strong>を始めたよ。これは、「恐怖の<ruby>均衡<rt>きんこう</rt></ruby>」から、自分だけが減らすのはイヤだけど、相手も一緒に核軍縮をするならOK、ってことだ。"
      ],
