      "title": "ソ連との武力不行使とポーランド国境",
      "body": [
        "1970年にはソ連との間で現在の国境の維持と武力不使用を約束して、<strong class=\"source-bold\">ソ連と西</strong><strong class=\"source-bold\">ドイツの間の<ruby>冷戦<rt>れいせん</rt></ruby>を終わらせ</strong>（<strong class=\"source-bold\">ソ連＝西ドイツ武力不行使条約【モスクワ条約】</strong>）、統一した際の<strong class=\"source-bold\">“ドイツ”とポーランドの国境を「オーデル＝ナイセ線」と確認</strong>して、<strong class=\"source-bold\">ポーランドとの国交正常化</strong>を実現した。"
      ],
      "plainBody": [
        "1970年にはソ連との間で現在の国境の維持と武力不使用を約束して、ソ連と西ドイツの間の冷戦を終わらせ（ソ連＝西ドイツ武力不行使条約【モスクワ条約】）、統一した際の“ドイツ”とポーランドの国境を「オーデル＝ナイセ線」と確認して、ポーランドとの国交正常化を実現した。"
      ],
