      "title": "交流から東欧民主化の土台へ",
      "body": [
        "（1995年には常設の全欧安全保障協力機構 <strong class=\"source-bold\">【</strong>OSCE<strong class=\"source-bold\">】</strong>となったよ）。そして、東西の人びとの交流が進むにつれて、東欧の社会主義国では反体制派の組織が拡大していったんだ。これが、のちの東欧の民主化の土台になっていくんだよ。"
      ],
