      "id": "modern-c05-l22-p02-037",
      "title": "第四次中東戦争と石油戦略",
      "body": [
        "そして1973年には、西側先進国を大きく揺るがす事件が起こったよ。10月に<ruby>勃発<rt>ぼっぱつ</rt></ruby>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4次中東戦争</strong></span>では、反イスラエルのアラブ産油国が結成した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OAPEC<rt>オアペック</rt></ruby></strong></span>】</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油戦略</strong></span>を始めたんだ。"
      ],
