      "title": "保守党とサッチャーの登場",
      "body": [
        "そして、労働党政権への不満から<strong class=\"source-bold\">総選挙では保守党が圧勝</strong>し、1979年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サッチャー</strong></span>が首相になったよ。彼女は<strong class=\"source-bold\">イギリス初の女性首相</strong>なんだけど、強いリーダーシップを発揮して、<strong class=\"source-bold\">「鉄の女」</strong>とも呼ばれたんだ。"
      ],
      "plainBody": [
        "そして、労働党政権への不満から総選挙では保守党が圧勝し、1979年、サッチャーが首相になったよ。彼女はイギリス初の女性首相なんだけど、強いリーダーシップを発揮して、「鉄の女」とも呼ばれたんだ。"
      ],
