      "title": "経済と技術の停滞",
      "body": [
        "ゴルバチョフは、「<strong class=\"source-bold\">今の状態のソ連で西側に対抗するのは不可能</strong>だ」と感じていた。だってソ連では、1980年代に入っても、農場も工場もほとんどが<ruby>鎌<rt>かま</rt></ruby>やハンマーの手作業……。こんな状態だから、経済成長率もほとんどゼロだ。こりゃ、経済が停滞するのは当たり前だよ。"
      ],
