      "id": "modern-c05-l22-p03-071",
      "title": "両大国を軍縮へ向かわせた財政",
      "body": [
        " そして、この米ソ首脳会談で話し合われたのは、ズバリ核軍縮！ ゴルバチョフは「ソ連の経済再建のためには<strong class=\"source-bold\">軍事費の削減が必要</strong>で、しかもアメリカの戦略防衛構想に対抗するのは、<strong class=\"source-bold\">ソ連の経済力と技術力では無理</strong>だ」と思っていたし、レーガンも「<strong class=\"source-bold\"><ruby>双子<rt>ふたご</rt></ruby>の赤字</strong>で、これまでのような<strong class=\"source-bold\"><ruby>軍拡<rt>ぐんかく</rt></ruby>路線は不可能</strong>だ」と思っていたから、お互いに歩み寄ったってわけ。"
      ],
