      "title": "ワレサと連帯の結成",
      "body": [
        "すでに1980年には、共産党（＝政府）の指導を受けずに自分たちのことは自分たちで決める！という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自主管理労組</strong></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">「<ruby>連帯<rt>れんたい</rt></ruby>」</strong></span>を結成して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワレサ</strong></span>を議長に、全国で自由化を求めるストライキをやっていた。"
      ],
      "plainBody": [
        "すでに1980年には、共産党（＝政府）の指導を受けずに自分たちのことは自分たちで決める！という自主管理労組「連帯」を結成して、ワレサを議長に、全国で自由化を求めるストライキをやっていた。"
      ],
