      "title": "ソ連国内の民主化要求",
      "body": [
        "1989年、東欧諸国で次々と共産党の一党独裁政権が倒れると、<strong class=\"source-bold\">ソ連国内でも民主化を求める動きが起こった。</strong>だって、これまで東ヨーロッパの民主化を<ruby>潰<rt>つぶ</rt></ruby>してきたソ連が、今回は動かなかったんだもん。そして、ソ連共産党の一党独裁体制に対する批判が高まり、"
      ],
