      "id": "modern-c05-l22-p04-027",
      "title": "党から国家へ、改革の予期しない帰結",
      "body": [
        "これは、<strong class=\"source-bold\">ソ連という「国」と共産党という「党」</strong>を切り離して、支配の中心を<strong class=\"source-bold\">「党から国家へ」</strong>と変えたということなんだけど、実はこの改革自体がソ連を崩壊させるものだと、この時には誰も気づいていなかった。もちろん、ゴルバチョフ本人も含めてね。"
      ],
