      "title": "経済と軍事の両組織を解体",
      "body": [
        "一方で、<ruby>冷戦<rt>れいせん</rt></ruby>の終結を受けて<strong class=\"source-bold\">社会主義陣営</strong>（共産圏）<strong class=\"source-bold\">の解体</strong>が一気に進んだよ。1991年6月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコンが解消</strong></span>され、7月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構が解体</strong></span>された。もう東欧に社会主義国が残っていないから、なくなって当然だよね。"
      ],
      "plainBody": [
        "一方で、冷戦の終結を受けて社会主義陣営（共産圏）の解体が一気に進んだよ。1991年6月にはコメコンが解消され、7月にはワルシャワ条約機構が解体された。もう東欧に社会主義国が残っていないから、なくなって当然だよね。"
      ],
