export const sourcePages = {
  "403": "<h2>403</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">冷戦の展開③（1970〜1991）</span></h1>\n<p>ベトナム戦争、東欧の社会主義陣営の動揺、世界各地で起こる反体制運動。米ソ2国による世界支配に限界が見えてきたね。そして、行き着く先は……、ついに<ruby>冷戦<rt>れいせん</rt></ruby>終結だ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><strong class=\"source-bold\">アメリカ合衆国の地位低下</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">404〜407ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td><td><strong class=\"source-bold\">米ソの行き詰まりと「新冷戦」</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">411〜416ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><strong class=\"source-bold\">デタント（緊張緩和）の進行と世界の多極化</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">407〜410ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span></td><td><strong class=\"source-bold\">冷戦の終結とソ連の崩壊</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">417〜422ページ</span></td></tr></tbody></table></div>\n<blockquote><p>いよいよ今回で冷戦終結だ！ 世界の激動を感じてもらえたらうれしいな</p></blockquote>\n<p>ベトナム戦争で経済が<ruby>疲弊<rt>ひへい</rt></ruby>したアメリカは、世界経済を支える力を失った。一方のソ連も膨大な軍事費を支えきれなくなってきた。こうして米ソ両国は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">デタント（緊張緩和）</u>に向かったんだ。そして同じ時期にヨーロッパでもデタントが進み、対立が少しずつ解決するのかと思いきや……<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ソ連のアフガニスタン<ruby>侵攻<rt>しんこう</rt></ruby></u>をきっかけに米ソは対立に逆戻り、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">「新冷戦」</u>になった。しかし、1985年にソ連で<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ゴルバチョフ</u>が登場すると、世界はこれまでになかったような劇的な変化を経験するよ。世界が変わる瞬間だ！</p>\n<p>それじゃあ冷戦の3回目、ソ連の崩壊まで一気にいってみよう〜。</p>",
  "404": "<h2>404</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ合衆国の地位低下</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">世界の多極化とデタントの進行［1969〜73］</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソン</strong></span>大統領［任1969〜74］</td><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレジネフ</strong></span>第一書記<br>［任1964〜82］</td></tr><tr><td><u data-source-underline-color=\"red\" data-source-underline-style=\"double\" style=\"text-decoration-color:#e52715;text-decoration-style:double\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デタントの進行</strong></span></u><br><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td><td></td></tr><tr><td>※西独：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブラント</strong></span>首相の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方外交</strong></span>」<br><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ソ連＝西ドイツ武力不行使条約</strong>［1970］<br><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東西ドイツ基本条約</strong></span>［1972］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">⬇</span><br><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドル＝ショック</strong></span>［1971］</td><td><u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\"><strong class=\"source-bold\">米中接近が進む</strong></u><br><span data-source-color=\"red\" style=\"color:#e52715\">➡</span>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国の国連代表権交代</strong></span>［1971］</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">⬇</span><br><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソン訪中</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">➡</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">米中共同声明</strong>［1972］</span></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><strong class=\"source-bold\">ニクソン訪ソ</strong> <span data-source-color=\"gray\" style=\"color:#777777\">➡</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SALTⅠ</strong></span>調印［1972］</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム和平協定</strong></span>［1973］</span></td><td></td></tr><tr><td>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">拡大EC</strong></span>［1973］<br>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次石油危機</strong></span>［1973］</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ ベトナムからの撤退を公約に、ニクソン大統領が登場！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム戦争</strong></span>はアメリカの社会を大きく揺るがした。反戦運動で<strong class=\"source-bold\">アメリカ社会が分裂</strong>し、<strong class=\"source-bold\">財政難でアメリカの国際的な地位も低下</strong>した。そして、国内でも世界でもアメリカの正義に疑問を持つ人たちが現れて、アメリカの威信が大きく揺らぎ始めたんだ。こうして、ジョンソンは大統領選挙に出馬しないことを発表、かわって1969年、<strong class=\"source-bold\">ベトナムからの<ruby>撤退<rt>てったい</rt></ruby>を公約</strong>に大統領になったのが、共和党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソン</strong></span>だ。</p>\n<p>ニクソンにとって一番重要な課題は、<strong class=\"source-bold\">「どうやってベトナムから手を引くか？」</strong>という1点にあったといってもいい。国内の反戦運動を考えると、これ以上軍を増強して全面勝利するのは不可能だ。かといって、完全に撤退して南ベトナムを見捨てるとアメリカの全面的敗北になって、国際的な<ruby>威信<rt>いしん</rt></ruby>が地に落ちる……。ニクソンは<strong class=\"source-bold\">「<ruby>名誉<rt>めいよ</rt></ruby>ある撤退」</strong>を目指して、戦争の<strong class=\"source-bold\">「ベトナム化」</strong>を表明した（<strong class=\"source-bold\">ニクソン＝ドクトリン</strong>）。これは<strong class=\"source-bold\">アメ</strong></p>\n<blockquote><p>ベトナム戦争は、もはや「<ruby>大義<rt>たいぎ</rt></ruby>のない戦争」になっていたからね。撤退の仕方は難しいよ……</p></blockquote>",
  "405": "<h2>405</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国の地位低下</u></p></blockquote>\n<p><strong class=\"source-bold\">リカが撤退したあともベトナム人同士の戦争が続く</strong>ようにして、「アメリカは悪くない」って言いたいの……責任逃れだろ。だからアメリカは<strong class=\"source-bold\">南ベトナム軍を強化しながら時間をかけて撤退</strong>しようとしてたんだよ。</p>\n<p>しかし、事態はニクソンの思うようには進まない。国内では、撤退の発表を歓迎するどころか「すぐに全面撤退しろ！」という声が高まった。そしてもっと深刻だったのが、<strong class=\"source-bold\">アメリカの貿易赤字への転落</strong>だよ。1964年がアメリカの貿易黒字のピークなんだけど、<strong class=\"source-bold\">ベトナム戦争の戦費</strong>や<strong class=\"source-bold\">「偉大な社会」</strong>計画での社会政策費でインフレーションが起こり、さらに<strong class=\"source-bold\">日本や西欧の高度経済成長とEC成立</strong>で輸出が減少したことから、徐々に貿易収支が悪化、ついに<strong class=\"source-bold\">1971年、貿易収支が赤字に転落</strong>した。しかも、ベトナム戦争で財政難だし……。もはや、どうにもならん。</p>\n<h4><strong class=\"source-bold\">アメリカの貿易収支</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>10億ドル</td><td>8 6 4 2 0 −2 −4 −6 −8</td></tr><tr><td></td><td>1950 1955 1960 1965 1970</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">1964年　貿易黒字のピーク</strong></span></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">1965年　北爆開始（ベトナム戦争）</strong></span></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">1971年　貿易赤字に転落<br>➡ドル＝ショック</strong></span></td><td></td></tr></tbody></table></div>\n<blockquote><p>このグラフ、アメリカ経済を見るうえでむちゃくちゃ重要だよ。このグラフが好きなのが慶應の経済学部ね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ニクソンが世界に与えた衝撃、1つ目は「ドル＝ショック」だ！</strong></span></h4>\n<p>ニクソンは貿易赤字を縮小させるため、1971年8月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金とドルの<ruby>兌換<rt>だかん</rt></ruby></strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">交換</strong></span>）<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">停止</strong></span>を発表（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドル＝ショック</strong></span>／ニクソン＝ショック）、<strong class=\"source-bold\">ドルを切り下げて</strong>（<strong class=\"source-bold\">ドル<ruby>安<rt>やす</rt></ruby>政策</strong>）アメリカの輸出競争力を復活させようとしたんだ。でも、通貨を下げたことで、世界に「アメリカ経済は限界なのか？」という不安を抱かせ、さらに<strong class=\"source-bold\">ドルの信用と価値が大きく下落</strong>した！。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドル危機</strong></span>で、アメリカ＝ドルが世界経済を支える経済システム、<strong class=\"source-bold\">ブレトン＝ウッズ体制が<ruby>崩壊<rt>ほうかい</rt></ruby></strong>したんだ。</p>\n<p>さらに同年12月に開かれた<strong class=\"source-bold\">スミソニアン会議</strong>では、資本主義側の各国が<strong class=\"source-bold\">通貨レートを再調整</strong>して、ドルの切り下げ、金との兌換停止の継続などを確認した（<strong class=\"source-bold\">スミソニアン体制</strong>）。例えば、日本円は1ドル＝360円から1ドル＝308円になったよ。しかし、これでも米ドルの信用は落ち続け、ついに完全な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">変動相場制</strong></span>が導入されたんだ。現在、ニュースで毎日「今日の円相場は1ドル＝○○円」って伝えているのは、この時からつねに相場が変わるようになったからだよ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "406": "<h2>406</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<h4><strong class=\"source-bold\">〈ブレトン＝ウッズ体制の崩壊〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"gray\" data-source-border-style=\"dashed\" style=\"border:1px dashed #777777;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ合衆国</strong></span></td><td></td><td></td></tr><tr><td><span data-source-border=\"brown\" data-source-border-style=\"solid\" style=\"border:1px solid #a43725;padding:0 0.2em\"><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">金</strong></span></span></td><td><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"text-decoration:line-through;text-decoration-color:#001000\"><span data-source-color=\"brown\" style=\"color:#a43725\">⇄</span></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米ドル</strong></span></span></td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">兌換停止<br>（ドル＝ショック）</strong></span></td><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">価値が下落</strong></span></td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\">⇄</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">英ポンド</strong></span></td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\">⇄</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">仏フラン</strong></span></td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\">⇄</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">日本円</strong></span></td></tr><tr><td></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">変動相場制<br>（つねに変わる）</strong></span></td><td></td></tr></tbody></table></div>\n<blockquote><p>例えば日本円だと、「360円→308円→変動相場制」って変化した。変動相場制になった直後に、1ドル＝260円まで円高が進んだよ</p></blockquote>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ もう一つの「ニクソン＝ショック」は、中国への接近！</strong></span></h4>\n<p>ニクソンは、<strong class=\"source-bold\">ベトナム戦争終結のきっかけをつくるために、中国との関係改善</strong>を図った。ただ、国連にはアメリカの同盟国である台湾（中華民国）がいるから、大っぴらに動くわけにもいかない。そこで、表に出てこないさまざまなルートで中国に接近したよ。例えば、日本で開かれた卓球の世界選手権の際に、卓球のアメリカ選手団（CIAのエージェントが混じっていたんだって）が中国に招かれ、これをきっかけに「アメリカ大統領を中国に招待したい」という極秘のメッセージがニクソンに届けられた（入試には出ないけど、「ピンポン外交」って呼ばれている）。<strong class=\"source-bold\">中国側も中ソ国境紛争を抱えていたから、ソ連を<ruby>牽制<rt>けんせい</rt></ruby>するためにアメリカと接近</strong>したかったんだね。</p>\n<p>そして、大統領補佐官の<strong class=\"source-bold\">キッシンジャー</strong>がこれまた極秘に中国を訪問して<strong class=\"source-bold\">ニクソンの訪中を決定</strong>し、全世界に発表した！。この発表は金とドルの兌換停止発表の1カ月前だから、2カ月連続で全世界に「ショック」を与えたことになるね。また、訪中と引き換えに<strong class=\"source-bold\">アメリカが中国の国連加盟を支持</strong>することになり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国の国連代表権交代</strong></span>が実現、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>が国連に加盟し、<strong class=\"source-bold\">台湾は国連を追放</strong>されたんだ。</p>\n<p>1972年2月、約束通り<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソンが訪中</strong></span>して<strong class=\"source-bold\">米中共同声明</strong>を発表し、<strong class=\"source-bold\">事実上中華人民共和国を承認</strong>したよ。ただ、台湾に駐留している米軍の問題やアメリカの議会との関係で、台湾政府とすぐに断交はできないから、<strong class=\"source-bold\">中華人民共和国との正式な国交正常化は1979年</strong>だよ<span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\">➡P.412</span>。そして、この突然の米中接近に焦ったのは日本だ！。そこで9月には<strong class=\"source-bold\"><ruby>田中角栄<rt>たなかくえい</rt></ruby>首相が中国を訪問</strong>、「日本と中国の戦争が終結した」ことを確認する<strong class=\"source-bold\">日中共同声明</strong>を発表、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中国交正常化</strong></span>を実現したよ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">◀ ベトナムからは<ruby>撤退<rt>てったい</rt></ruby>したけど……ウォーターゲート事件でニクソンが辞任！</strong></span></h4>\n<p>ニクソンが中国に接近した目的は、最終的には<strong class=\"source-bold\">ベトナムからの「<ruby>名誉<rt>めいよ</rt></ruby>ある撤退」</strong>だから、もう1つのコマが必要だ。それは<strong class=\"source-bold\">ソ連の協力</strong>だよ。だって、<strong class=\"source-bold\">アメリカが南ベトナムを支援</strong>しているように、<strong class=\"source-bold\">ソ連は北ベトナムを支援</strong>しているんだもん。戦争</p>",
  "407": "<h2>407</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">デタント（緊張緩和）の進行と世界の多極化</u></p></blockquote>\n<p>終結にはソ連の協力が不可欠だよ。</p>\n<p>そして、<strong class=\"source-bold\">ソ連も米中の接近に焦っていた</strong>。米中が組んでしまったら、国際社会でのソ連の影響力が大きく落ちてしまう。ソ連は、ニクソンの訪中予告を聞いてすぐに、<strong class=\"source-bold\">ニクソンにソ連訪問を要請</strong>したんだけど、答えは「中国のあとで」。そりゃそうだろうね。ソ連を動かすために中国を使ったんだからさ。</p>\n<p>そして5月、ニクソンは<strong class=\"source-bold\">戦後初めてアメリカ大統領としてソ連を訪問</strong>した（<strong class=\"source-bold\">ニクソン訪ソ</strong>）。そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SALT<rt>ソルト</rt></ruby>Ⅰ</strong></span>に調印するとともに、ベトナム戦争終結に向けたソ連の協力を取りつけたんだよ。そして、1973年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベトナム和平協定</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ和平協定</strong></span>】</strong>が結ばれ、<strong class=\"source-bold\">アメリカ軍のベトナムからの撤退</strong>が決まったんだ。ただし、戦争の「ベトナム化」によって<strong class=\"source-bold\">南ベトナムへの武器援助は続き</strong>、ベトナムではこのあと約2年間も戦争が続いたんだよね。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">↔</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦</strong></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">米</strong></span></td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">↕</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span></td><td></td><td><strong class=\"source-bold\">米中接近</strong></td></tr><tr><td><span data-source-border=\"pink\" data-source-border-style=\"solid\" style=\"border:1px solid #f0a0a0;padding:0 0.2em\"><strong class=\"source-bold\">中国</strong></span></td><td><span data-source-color=\"black\" data-source-marker=\"double-line\" style=\"color:#001000;border-bottom:3px double #001000\">━</span></td><td></td></tr></tbody></table></div>\n<blockquote><p>対立関係をしっかりおさえてね！</p></blockquote>\n<p>ベトナムからの撤退を確実に進めたニクソンは、<strong class=\"source-bold\">2期目の大統領選挙で圧勝</strong>した。ただ、そこに落とし穴があった。訪中、訪ソ、ベトナム撤退、確かに難題は多かったけど、それらをニクソンはあまり議会に配慮せず、強引に進めてきた。実はその政治のなかで危ないウラ工作もやってきたんだよ。そして、<strong class=\"source-bold\">大統領選挙の際の民主党本部への<ruby>盗聴<rt>とうちょう</rt></ruby>工作</strong>が発覚したのをきっかけにさまざまな<ruby>汚職<rt>おしょく</rt></ruby>や違法行為を追及され、大統領周辺の人物に次々と有罪判決が出された。そしてついに<strong class=\"source-bold\">議会でも大統領の<ruby>弾劾<rt>だんがい</rt></ruby>が話し合われた</strong>！。この<strong class=\"source-bold\">ウォーターゲート事件</strong>で、ニクソンは辞任したんだよ。大統領の辞任は異例のことだ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">デタント（緊張緩和）の進行と世界の多極化</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ベトナム戦争や中ソ対立で米ソの地位が低下、<ruby>核軍縮<rt>かくぐんしゅく</rt></ruby>が前進した！</strong></span></h4>\n<p>ここで、いったん時代をさかのぼって、<strong class=\"source-bold\">米ソの核軍縮</strong>について見ていこう。民間では1950年代から核兵器への反核運動が起きていた。きっかけは、アメリカによる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビキニ<ruby>環礁水爆<rt>かんしょうすいばく</rt></ruby>実験</strong></span>で日本の漁船が<ruby>被曝<rt>ひばく</rt></ruby>した、1954年の<strong class=\"source-bold\">第五<ruby>福竜丸<rt>ふくりゅうまる</rt></ruby>事件</strong>だ！。ここから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">原水爆禁止運動</strong></span>が始まり、また哲学者の<strong class=\"source-bold\">ラッセルと物理学者のアインシュタインを中心に科学者たちも核兵器禁止を訴え</strong>、1957年にはカナダで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パグウォッシュ会議</strong></span>が開かれたんだ。でも、米ソをはじめとする核保有国は核開発競争をやめなかった。しかし<strong class=\"source-bold\">部分的核実験禁止条約締結</strong>のあと、少しずつだけど核軍縮に向けた歩みが始まったよ。背景は財政難っていう面もあるんだけど。</p>\n<p>アメリカでは<strong class=\"source-bold\">ベトナム戦争の戦費が財政を圧迫</strong>し、ジョンソン大統領は「偉大な社会」計画を<ruby>諦<rt>あきら</rt></ruby>めるしかなかった。一方のソ連も、もともと産業がそこまで強くないのに<strong class=\"source-bold\">アメリカと並ぶ核保有国の地位を維持</strong>するために、<strong class=\"source-bold\">膨大な軍事費</strong>を使ってい</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "408": "<h2>408</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>たけど、それも限界に近づきつつあったんだ。しかも米ソ両国を悩ませたのは、<strong class=\"source-bold\">フランスと中国が<ruby>核<rt>かく</rt></ruby>実験に成功</strong>して、核の独占も崩れてしまったことだ。これ以上核保有国を増やしたくないのは、米ソどちらも同じこと。ベトナム戦争での対立は棚上げして、米ソ両国は核兵器の不拡散で一致した。</p>\n<p>1968年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核拡散防止条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">NPT</strong></span>】</strong>が<strong class=\"source-bold\">米・英・ソ</strong>など62カ国によって調印され、核保有国を、<strong class=\"source-bold\">アメリカ・イギリス・ソ連・フランス・中国</strong>の5カ国に限定し、この時点で<strong class=\"source-bold\">核兵器を持っていない国</strong>（<strong class=\"source-bold\">非核保有国</strong>）<strong class=\"source-bold\">への核兵器の<ruby>譲渡<rt>じょうと</rt></ruby>や製造の援助を禁止</strong>したんだ。ただ、<strong class=\"source-bold\">フランスと中国は</strong>すでに米ソに対抗して連携していたから、条約には<strong class=\"source-bold\">不参加</strong>だ（参加したのは1992年）。さらに、この条約は核保有そのものを禁止したわけじゃないから、<strong class=\"source-bold\">核保有国にはなんの制限もない</strong>。これに反発した<strong class=\"source-bold\">インド、パキスタン、イスラエルなどは<ruby>締結<rt>ていけつ</rt></ruby>を拒否</strong>し、現在は<strong class=\"source-bold\">核保有国</strong>になっちゃったんだ（イスラエルの核保有は公然の秘密だから、入試では「核を保有しているかわからない」が正解だけど……）。</p>\n<p>そして1969年、米ソ両国は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦略兵器制限交渉</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SALT<rt>ソルト</rt></ruby></strong></span>】</strong>を始めたよ。これは、「恐怖の<ruby>均衡<rt>きんこう</rt></ruby>」から、自分だけが減らすのはイヤだけど、相手も一緒に核軍縮をするならOK、ってことだ。そして、ニクソンが訪中を予告したからソ連側が歩み寄り、両国が合意、1972年、ソ連を訪問した<strong class=\"source-bold\">ニクソン</strong>とソ連の<strong class=\"source-bold\">ブレジネフ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SALTⅠ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次戦略兵器制限交渉</strong></span>】</strong>で合意に達したよ。ただ、この条約も核<ruby>弾頭<rt>だんとう</rt></ruby>（爆弾そのもの）を削減するわけではなく、おもに<strong class=\"source-bold\">大陸間弾道弾【ICBM】の数</strong>や、<strong class=\"source-bold\">弾道弾迎撃ミサイル【AMB】を制限</strong>するものだから、制限されていない部分が多すぎて、抜け道だらけだよ。</p>\n<p>そうはいっても、対話に向かい始めた米ソ両国は、ブレジネフが訪米したり、ニクソンが再び訪ソするなど<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">デタント</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">緊張<ruby>緩和<rt>かんわ</rt></ruby></strong></span>】</strong>に向かい、さらなる核軍縮に向けて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SALTⅡ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次戦略兵器制限交渉</strong></span>】</strong>の交渉も始まったよ。そして米ソのデタントが進んだ影響で、<strong class=\"source-bold\">ヨーロッパのデタント</strong>も進むんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ブラントの「東方外交」で、ヨーロッパのデタントが進行！</strong></span></h4>\n<p>戦後、<strong class=\"source-bold\">西ドイツ</strong>はずっと「ドイツの東西分断」を拒否して、東ドイツの存在を認めていなかった。ただ、この政策が1961年の「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンの<ruby>壁<rt>かべ</rt></ruby></strong></span>」建設など、東ドイツとの関係をますます悪化させ、<strong class=\"source-bold\">ドイツの分裂を固定化</strong>してしまったんだ。そこで、西ドイツの外交方針を180度転換したのが、1969年に首相となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会民主党</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブラント</strong></span>だよ。彼の進めた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東方外交</strong></span>」は、ズバリ<strong class=\"source-bold\">“社会主義陣営との和解”</strong>だ。</p>\n<p>そもそも、ドイツの東西分断を認めない、つまり「<strong class=\"source-bold\">東ドイツという国は存在しない！</strong> 共産主義者が不法に<ruby>占拠<rt>せんきょ</rt></ruby>している」という立場だと<strong class=\"source-bold\">話し合いができない</strong>から、ドイツ統一の方法は「ドイツ戦争」しかなくなる。そこでブラントは<strong class=\"source-bold\">「東ドイツの存在を承認する」</strong>「ヨーロッパの現在の国境、特にポーランドとの国境も認める」という立場をとって、<strong class=\"source-bold\">社会主義国との対話を進める</strong>という方針を示したんだ。1970年にはソ連との間で現在の国境の維持と武力不使用を約束して、<strong class=\"source-bold\">ソ連と西</strong></p>",
  "409": "<h2>409</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">デタント（緊張緩和）の進行と世界の多極化</u></p></blockquote>\n<p><strong class=\"source-bold\">ドイツの間の<ruby>冷戦<rt>れいせん</rt></ruby>を終わらせ</strong>（<strong class=\"source-bold\">ソ連＝西ドイツ武力不行使条約【モスクワ条約】</strong>）、統一した際の<strong class=\"source-bold\">“ドイツ”とポーランドの国境を「オーデル＝ナイセ線」と確認</strong>して、<strong class=\"source-bold\">ポーランドとの国交正常化</strong>を実現した。さらに1972年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東西ドイツ基本条約</strong></span>を結んで、東西ドイツ両国が相手の主権を確認すると、翌年には、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国連への同時加盟</strong></span>を果たした。こうして2国間のデタントを進めることでヨーロッパ全体の対立を緩和し、<strong class=\"source-bold\">将来のドイツ統一へと一歩前進</strong>した功績から、ブラントは<strong class=\"source-bold\">ノーベル平和賞を受賞</strong>したんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">西独</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">↔</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">東独</strong></span></td></tr><tr><td><span data-source-color=\"black\" style=\"color:#001000\">━</span> <span data-source-color=\"black\" data-source-marker=\"curved-line\" style=\"color:#001000\">━</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">衛星国</span> <span data-source-color=\"black\" data-source-marker=\"double-line\" style=\"color:#001000;border-bottom:3px double #001000\">━</span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ポーランド</strong></span></td><td><span data-source-color=\"black\" data-source-marker=\"double-line\" style=\"color:#001000;border-bottom:3px double #001000\">━</span></td><td></td></tr></tbody></table></div>\n<blockquote><p>ブラントは東ドイツとの関係改善のため、周りを固めたんだ！</p></blockquote>\n<p>そして、ブラントの「東方外交」によってヨーロッパ全体のデタントが進み、1975年には米ソを含む35カ国による<strong class=\"source-bold\">全欧安全保障協力会議【CSCE】</strong>が開かれ、<strong class=\"source-bold\">ヘルシンキ宣言</strong>が<ruby>採択<rt>さいたく</rt></ruby>された。ヘルシンキ宣言では、<strong class=\"source-bold\">ヨーロッパの国境の現状維持</strong>を確認したうえで、<strong class=\"source-bold\">経済や科学技術の協力</strong>を進め、<strong class=\"source-bold\">人的交流や人権の尊重</strong>を進めることを約束した（1995年には常設の全欧安全保障協力機構 <strong class=\"source-bold\">【</strong>OSCE<strong class=\"source-bold\">】</strong>となったよ）。そして、東西の人びとの交流が進むにつれて、東欧の社会主義国では反体制派の組織が拡大していったんだ。これが、のちの東欧の民主化の土台になっていくんだよ。</p>\n<p>ちなみに、この時期の<strong class=\"source-bold\">西ヨーロッパでは社会主義政党の政権が多かった</strong>んだ。だからといって、いきなりソ連の言うことを聞いたりはしない。もちろん、<strong class=\"source-bold\">複数政党制</strong>や<strong class=\"source-bold\">議会政治</strong>という資本主義（自由主義）国では当たり前の体制は維持されたから国家の体制が大きく変わるわけじゃない。これも、この時期に進んだデタントの影響だ。こうした社会主義（共産主義）を<strong class=\"source-bold\">ユーロコミュニズム</strong>と呼んでいる。例えば、さっき話した<strong class=\"source-bold\">西ドイツの社会民主党政権</strong>（<strong class=\"source-bold\">ブラント</strong>［任1969〜74］、シュミット［任1974〜82］）や、<strong class=\"source-bold\">イギリスの労働党政権</strong>（<strong class=\"source-bold\">ウィルソン</strong>［任1974〜76］、キャラハン［任1976〜79］）、さらに時期は少しあとになるけど、<strong class=\"source-bold\">フランス社会党のミッテラン</strong>［任1981〜95］が大統領になったのも、こうしたユーロコミュニズムの動きだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 拡大EC、サミットの開始、資本主義陣営の枠組みが変化した！</strong></span></h4>\n<p>1970年代に入ると、西側諸国のなかで国際関係に変化が現れたよ。60年代はフランスのド＝ゴールが独自路線で米英に対抗していたけど、69年に退陣した。そして、<strong class=\"source-bold\">ECの中心だった独仏の関係に変化が生まれる</strong>んだ。というのも、60年代にフランス・西ドイツは高度経済成長したんだけど、圧倒的に西ドイツのほうがすごかったんだよ。だから、<strong class=\"source-bold\">西ドイツだけが強くなるの</strong></p>\n<blockquote><p>ド＝ゴールが引退したら、イギリスはECに加盟できたよ。結局、全部ド＝ゴールのせいじゃん</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "410": "<h2>410</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p><strong class=\"source-bold\">を警戒したフランスが、イギリスの加盟承認に動いた</strong>んだ。てか、ド＝ゴールがずっと拒否し続けてたのと大違い。</p>\n<p>こうして、1973年1月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>・<strong class=\"source-bold\">アイルランド・デンマーク</strong>の3国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ECに加盟</strong></span>したよ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">拡大EC</strong></span>）。その後、加盟国はさらに増え、<strong class=\"source-bold\">ギリシア</strong>［1981］、<strong class=\"source-bold\">スペイン・ポルトガル</strong>［1986］がそれぞれ加盟して、<strong class=\"source-bold\">EC加盟国は12カ国</strong>になったんだ。</p>\n<p>そして1973年には、西側先進国を大きく揺るがす事件が起こったよ。10月に<ruby>勃発<rt>ぼっぱつ</rt></ruby>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4次中東戦争</strong></span>では、反イスラエルのアラブ産油国が結成した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OAPEC<rt>オアペック</rt></ruby></strong></span>】</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油戦略</strong></span>を始めたんだ。石油戦略とは、すごく簡単に言うと<strong class=\"source-bold\">「イスラエルに味方する国には石油を売ってやんない作戦」</strong>だ。で、アメリカがイスラエルを全面支援しているから、<strong class=\"source-bold\">「イスラエルの味方＝アメリカの味方」</strong>となり、西側の先進国への石油輸出をストップした。これが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次石油危機</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オイル＝ショック</strong></span>】</strong>だよ。しかも、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OPEC<rt>オペック</rt></ruby></strong></span>】</strong>も原油価格を大幅に引き上げたから、<strong class=\"source-bold\">西側諸国では物価が<ruby>高騰<rt>こうとう</rt></ruby></strong>し、しかも<ruby>不況<rt>ふきょう</rt></ruby>という最悪の状態（<strong class=\"source-bold\">スタグフレーション</strong>）になった。特にアメリカは、この2年前のドル＝ショックとあわせて、経済的な地位がさらに低下したんだよ。そして、これまで安い原油に支えられていた西側の先進国は、世界経済の構造そのものについて考えさせられたんだ。</p>\n<p>1975年、<strong class=\"source-bold\">フランス大統領ジスカールデスタン</strong>の提唱で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1回サミット</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">先進国首脳会議</strong></span>】</strong>が開かれたよ。参加したのは、<strong class=\"source-bold\">米・英・仏・西独・伊・日本</strong>（翌年に<strong class=\"source-bold\">カナダ</strong>も加えた7カ国が<strong class=\"source-bold\">G7</strong>。ソ連崩壊後、ロシアも入れる場合はG8だ）で、以後サミットはほぼ毎年開かれ、その時期の重要な課題について話し合っているよ。もちろん、第1回の主要テーマは「石油を中心とするエネルギー問題」だ。</p>\n<h4><strong class=\"source-bold\">＜ヨーロッパ共同体【EC】（1993年以降はヨーロッパ連合【EU】）加盟国＞</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>加盟年</td><td>新規加盟国</td></tr><tr><td>原加盟国</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フランス・西ドイツ</strong></span>（東西ドイツ統一［1990］後はドイツ）・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア・ベルギー・オランダ・ルクセンブルク</strong></span></td></tr><tr><td>1973</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス</strong></span>・<strong class=\"source-bold\">アイルランド・デンマーク</strong></td></tr><tr><td>1981</td><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td>1986</td><td><strong class=\"source-bold\">スペイン・ポルトガル</strong></td></tr><tr><td>1995</td><td><strong class=\"source-bold\">オーストリア・スウェーデン・フィンランド</strong></td></tr><tr><td>2004</td><td>エストニア・ラトヴィア・リトアニア・ポーランド・チェコ・スロヴァキア・ハンガリー・スロヴェニア・マルタ・キプロス</td></tr><tr><td>2007</td><td>ブルガリア・ルーマニア</td></tr><tr><td>2013</td><td>クロアティア</td></tr></tbody></table></div>",
  "411": "<h2>411</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">米ソの行き詰まりと「新冷戦」</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">米ソの行き詰まりと「新冷戦」</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">デタントから新冷戦へ［1977〜87］</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーター</strong></span>大統領［任1977〜81］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">「人権外交」</strong>を推進</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレジネフ</strong></span>書記長<br>［任1964〜82／66年までは第一書記］</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米中国交正常化</strong></span>［1979］</span><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝イスラエル平和条約</strong></span>［1979］</span><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">SALTⅡ</strong></span>［1979］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span><br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連、アフガニスタン<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>［1979.12］</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">↙</span><br><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーガン</strong></span>大統領［任1981〜89］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">「強いアメリカ」</strong>を主張<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">戦略防衛構想【SDI】</strong>発表<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<strong class=\"source-bold\"><ruby>双子<rt>ふたご</rt></ruby>の赤字</strong>」の拡大<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">プラザ合意</strong>［1985］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>アメリカ財政の行き詰まり</td><td>※共産圏の動揺<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド自主管理労組</strong></span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>連帯<rt>れんたい</rt></ruby></strong></span>」<br><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ</strong></span>書記長就任［1985］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペレストロイカ</strong></span>」<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グラスノスチ</strong></span>」<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェルノブイリ原発事故</strong></span>が契機<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">「新思考外交」</strong></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">➡</span> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中距離核戦力全廃条約</strong></span>［1987］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ニクソン辞任の反動で、クリーンなイメージのカーター大統領が登場！</strong></span></h4>\n<p>それじゃあ、再びアメリカに戻ろう。<strong class=\"source-bold\">ウォーターゲート事件でニクソンが辞任</strong>すると、副大統領の<strong class=\"source-bold\">フォード</strong>が大統領になったんだけど、「ニクソンは大統領を辞めて責任を取ったから、これ以上追及しない」と言っちゃった。この時点で、彼の運命は決まったようなもんだ。もはや地に落ちたアメリカ大統領の<ruby>威信<rt>いしん</rt></ruby>が回復できないまま任期を終えたよ。一応、<strong class=\"source-bold\">第1回サミットに出席したのはフォード</strong>だけど、提唱したのはフランス。アメリカの存在感がこんなになかったのは、この時だけかもね。こうなると、次の大統領選挙は誰が出ても民主党が勝ちだよ。こうして1977年、汚職のないクリーンなイメージの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーター</strong></span>が大統領になったんだ。</p>\n<p>カーターは、「“自由で平等で人権を尊重する”のがアメリカ的な価値観なのに、これまでのアメリカ外交はそこからかけ離れているじゃないか」と主張して、<strong class=\"source-bold\">「人権外交」</strong>を進めたんだ。簡単に言うと<strong class=\"source-bold\">「人権を守る国と仲良くする」</strong>、そして最</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "412": "<h2>412</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>後は<strong class=\"source-bold\">「話せばわかる！」</strong>って感じかな。</p>\n<p>まず、1977年に<strong class=\"source-bold\">新パナマ運河条約</strong>を結んで、アメリカが永久<ruby>租借<rt>そしゃく</rt></ruby>権を持っていた<strong class=\"source-bold\">パナマ運河地帯を返還</strong>することを決めた。さらに1979年になると、1月にソ連への対抗から中国との関係を完全に正常化し（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米中国交正常化</strong></span>）、<strong class=\"source-bold\">台湾国民政府とは断交</strong>した。さらに3月には、カーターの仲介によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝イスラエル平和条約</strong></span>が結ばれ、中東和平は大きく前進したようにも見えた。そしてソ連とは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>SALT<rt>ソルト</rt></ruby>Ⅱ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次戦略兵器制限交渉</strong></span>】</strong>を進め、第1次よりも踏む込んだ内容で調印にこぎつけたよ。</p>\n<blockquote><p>「話せばわかる！」っていう人権外交は、話してわかる人が出てこないと成立しないんだよ……</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 反米の事件が次々と起こり、「人権外交」が<ruby>破綻<rt>はたん</rt></ruby>！</strong></span></h4>\n<p>でも、カーターの「人権外交」は最初から矛盾を抱えていたよ。そもそも<strong class=\"source-bold\">アメリカが支援している同盟国は、全部が民主主義の国ってわけじゃない</strong>し、特にラテンアメリカでは、何度も<ruby>左翼<rt>さよく</rt></ruby>政権を<ruby>潰<rt>つぶ</rt></ruby>して親米の軍事<ruby>独裁<rt>どくさい</rt></ruby>政権をつくっている。一例を挙げると、1970年にできたチリの<strong class=\"source-bold\">アジェンデ</strong>政権は<strong class=\"source-bold\">史上初めて選挙で成立した社会主義政権</strong>だったけど、アメリカの支援するクーデタで<strong class=\"source-bold\">ピノチェト</strong>軍事政権ができた。彼らに「人権を守れ！」なんて言ったら、自分の独裁政治を否定することになるから当然反発が起こるし、逆に「アメリカが応援してくれてるのでは？」と思った<strong class=\"source-bold\">反体制派による独裁政権への反対運動</strong>が激化してしまう。</p>\n<p>こうした矛盾もあって、1979年に入ると、世界各地で<strong class=\"source-bold\">カーターの「人権外交」を破綻させる事件</strong>が次々と起きた。まず1月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホメイニ</strong></span>が指導する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン革命</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イスラーム革命</strong></span>】</strong>が起きて、親米の国王<strong class=\"source-bold\">パフレヴィー2世</strong>が<ruby>亡命<rt>ぼうめい</rt></ruby>に追い込まれ、新たにできた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イスラーム共和国</strong></span>は「反米」を主張、11月にはアメリカ大使館員を人質として、前国王の身柄と資産の引き渡しを要求してきた（<strong class=\"source-bold\">イラン＝アメリカ大使館人質事件</strong>）。さらにカーターが命令した救出作戦も失敗したから、アメリカでは<strong class=\"source-bold\">カーター政権への失望感が広がった</strong>んだ。しかも、7月には中米の<strong class=\"source-bold\">ニカラグア</strong>で、<strong class=\"source-bold\">サンディニスタ民族解放戦線</strong>が親米の<strong class=\"source-bold\">ソモサ軍事政権</strong>を倒す<strong class=\"source-bold\">ニカラグア革命</strong>が起き、左翼政権ができた。</p>\n<p>そして、カーター政権にトドメを刺したのが、12月に起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連のアフガニスタン<ruby>侵攻<rt>しんこう</rt></ruby></strong></span>だよ！。アフガニスタンでは1978年にすでに社会主義的な政権ができていたんだけど、革命勢力の内部対立が激化していたため、<strong class=\"source-bold\">ソ連のブレジネフはアフガニスタンに直接<ruby>介入<rt>かいにゅう</rt></ruby></strong>して、全土を制圧したんだ。</p>\n<p>こうした社会主義勢力の拡大、特にソ連のアフガニスタン侵攻に対し、カーターは有効な対抗策を打ち出せなかった。だって、「話せばわかる！」って言っても、話し合いができない人が出てきたら破綻する。<strong class=\"source-bold\">カーター政権は「弱腰外交」だと批判された</strong>。そして、上院は「信用できないソ連との条約は<ruby>批准<rt>ひじゅん</rt></ruby>できない！」と</p>",
  "413": "<h2>413</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">米ソの行き詰まりと「新冷戦」</u></p></blockquote>\n<p>反発、SALTⅡ<strong class=\"source-bold\">の批准も見送られ、さらに1980年のモスクワ五輪もボイコットした</strong>。こうして米ソ関係は急速に悪化、両国は再び軍備の拡大を進めて対立を深めた。デタントは一気に吹っ飛んで、世界は「<strong class=\"source-bold\">新<ruby>冷戦<rt>れいせん</rt></ruby></strong>」となったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「強いアメリカ」を唱えるレーガン大統領が登場。<ruby>軍拡<rt>ぐんかく</rt></ruby>に突っ走る！</strong></span></h4>\n<p>カーター政権の「人権外交」が破綻した1980年の大統領選挙では、俳優出身で「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">強いアメリカ</strong></span>」を主張する共和党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーガン</strong></span>が当選した。レーガンは、もともと西部劇にたくさん出演している俳優で、見た目は明るくおおらかな典型的アメリカ人だったけど、その政策はかなり強硬だ！ ソ連を<strong class=\"source-bold\">「悪の帝国」</strong>と呼んで対決姿勢を鮮明にすると、<strong class=\"source-bold\"><ruby>核<rt>かく</rt></ruby>軍拡</strong>へと一直線。いきなり5年間で1兆5000億ドルの軍事費を使うと発表し、<strong class=\"source-bold\">戦略防衛構想【SDI】</strong>、通称“スターウォーズ計画”を打ち出した。これは、ソ連から飛んでくるミサイルを宇宙空間で迎撃し破壊するというもので、当時人気のあった<strong class=\"source-bold\">映画「スターウォーズ」の世界そのもの</strong>だった。さらに、猛烈な勢いで核兵器の配備拡大に突っ走ったんだ。</p>\n<p>これには、さすがに<strong class=\"source-bold\">西ヨーロッパ各国が焦った</strong>！。だって、アメリカが核軍拡を進めれば、当然ソ連が東欧への核兵器配備で対抗してくる。そうなると、<strong class=\"source-bold\">ヨーロッパが核軍拡競争の舞台</strong>になって、核戦争に巻き込まれるんじゃないか？っていうのが西欧諸国の心配だ。こうして、<strong class=\"source-bold\">反核運動</strong>が高まったんだ。そして、<strong class=\"source-bold\">第2回国連<ruby>軍縮<rt>ぐんしゅく</rt></ruby>特別総会</strong>の際には、ニューヨークで100万人近い市民が参加する反核デモがおこなわれ、反核運動は世界的な広がりを見せ始めた。こうした動きを受けたレーガンは、さすがに核軍拡の主張だけを続けることもできなかった。そして、オモテでは「ソ連は“悪”」という非難を強めながら、<strong class=\"source-bold\">ウラでは核軍縮交渉を進めた</strong>んだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「<ruby>双子<rt>ふたご</rt></ruby>の赤字」が拡大して、アメリカ財政が危機に陥る！</strong></span></h4>\n<p>一方で、レーガン政権の「強いアメリカ」は、ラテンアメリカの<ruby>左翼<rt>さよく</rt></ruby>政権にも向けられたよ。社会主義政権ができたカリブ海の小国<strong class=\"source-bold\">グレナダに侵攻</strong>して政権を倒したり、<strong class=\"source-bold\">ニカラグアにも介入</strong>し、サンディニスタ政権に対し、<strong class=\"source-bold\">反政府勢力「コントラ」への軍事支援</strong>をしたりと、強硬な政策をとったんだ。</p>\n<p>また、国内では<strong class=\"source-bold\">レーガノミクス</strong>と呼ばれる<strong class=\"source-bold\">経済再建策</strong>を打ち出したよ。<strong class=\"source-bold\">社会福祉の切り捨てと行政改革</strong>によって<strong class=\"source-bold\">「小さな政府」</strong>を目指し、自由競争によって活発な経済を取り戻し（<strong class=\"source-bold\">新自由主義</strong>）、さらに<strong class=\"source-bold\">所得減税</strong>によって消費を拡大して景気を回復させれば、結果的に税収が増える、というのがレーガンの主張だ。ただ、レーガン政権は矛盾を抱えている。「<strong class=\"source-bold\">大規模な軍備拡大</strong>」で軍事費が増えているのに、減税をしたら財政赤字が拡大しちゃう。さらにアメリカを悩ませたのが<strong class=\"source-bold\">貿易赤字</strong>だよ。1980年代には<strong class=\"source-bold\">日本からの輸入が急増</strong>して、対日貿易赤字が拡大していた。特にオイル＝ショックをきっかけに技術革新に成功した日本車は、アメリカで売れまくった。あまりにも貿易赤字が拡大したから、アメリカは「日本の輸出を減らせ！ アメリカのものを買え！」と<ruby>市場<rt>しじょう</rt></ruby>開放と輸出の規制を要求した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日米貿易<ruby>摩擦<rt>まさつ</rt></ruby></strong></span>）。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "414": "<h2>414</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>こうしてアメリカは<strong class=\"source-bold\">「<ruby>双子<rt>ふたご</rt></ruby>の赤字」</strong>（<strong class=\"source-bold\">財政赤字</strong>と<strong class=\"source-bold\">貿易赤字</strong>）が拡大し、1985年ついに、<strong class=\"source-bold\">世界最大の<ruby>債務国<rt>さいむこく</rt></ruby></strong>となった。レーガンは口には出さなかったけど、レーガノミクスは失敗だよ。仕方なく各国は、ドル高の是正と為替レートの調整によってアメリカを助けることにした。1985年9月、ニューヨーク・プラザホテルで<strong class=\"source-bold\">G5【米・英・西独・仏・日】</strong>がアメリカの貿易赤字を減らすための<strong class=\"source-bold\">ドル<ruby>安<rt>やす</rt></ruby>政策に合意</strong>したんだ。</p>\n<p>この<strong class=\"source-bold\">プラザ合意</strong>に基づいて各国の中央銀行が協調してドル安に誘導したんだけど、貿易赤字が解消しないどころか、「アメリカ経済って、こんなにヤバいの？」っていう不信感が広がって、<strong class=\"source-bold\">ニューヨーク株式<ruby>市場<rt>しじょう</rt></ruby>で株価が大暴落</strong>したんだ（<strong class=\"source-bold\">ブラック＝マンデー</strong>）。そして、これまでアメリカに流れていた投資資金が日本に集まって、株価や土地の価格が異常なまでに<ruby>高騰<rt>こうとう</rt></ruby>、日本は<strong class=\"source-bold\">「バブル経済」</strong>になったんだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong>　<span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;padding:0 0.2em\"><strong class=\"source-bold\">戦後経済史のトピックス</strong></span></h4>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレトン＝ウッズ体制</strong></span>……アメリカが世界経済を支える</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際通貨基金</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">IMF</strong></span>】</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際<ruby>復興<rt>ふっこう</rt></ruby>開発銀行</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">IBRD</strong></span>】</strong>の設立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">米ドルを<ruby>基軸<rt>きじく</rt></ruby>通貨とする固定相場制</strong></p></blockquote>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドル＝ショック</strong></span>［1971］……アメリカの<strong class=\"source-bold\">貿易赤字転落</strong>が契機</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">金・ドルの<ruby>兌換<rt>だかん</rt></ruby>停止</strong><span data-source-color=\"green\" style=\"color:#315837\">➡</span>ドルの切り下げ、<strong class=\"source-bold\">変動相場制</strong>の導入</p></blockquote>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">プラザ合意</strong>［1985］……米が<strong class=\"source-bold\">世界最大の債務国</strong>となったことが契機</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">G5（米・英・西独・仏・日）</strong>が<strong class=\"source-bold\">ドル安政策</strong>に合意</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ じゃあ、この時期の西欧諸国はどうなっていたんだろう？</strong></span></h4>\n<p>では、同時期の西欧諸国の動きを見ておこう。まずはイギリスから。「イギリス病」とも呼ばれる<ruby>不況<rt>ふきょう</rt></ruby>から抜け出せないまま、労働者のストライキが激しくなり、イギリスでは、学校までもが閉鎖に追い込まれていた。そして、労働党政権への不満から<strong class=\"source-bold\">総選挙では保守党が圧勝</strong>し、1979年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サッチャー</strong></span>が首相になったよ。彼女は<strong class=\"source-bold\">イギリス初の女性首相</strong>なんだけど、強いリーダーシップを発揮して、<strong class=\"source-bold\">「鉄の女」</strong>とも呼ばれたんだ。サッチャーは、財政を立て直すため、<strong class=\"source-bold\">福祉の縮小</strong>や<strong class=\"source-bold\">国営企業の民営化</strong>など<strong class=\"source-bold\">「小さな政府」</strong>を目指し、これまで労働党が進めてきた政策を大転換して、「民間でできることは民間でやる」を基本に、<strong class=\"source-bold\">規制<ruby>緩和<rt>かんわ</rt></ruby>によって自由競争を活発にして</strong>、イギリス経済の再建を図った。この</p>\n<blockquote><p>「鉄の女」と呼ばれるほど強力なリーダーだったサッチャーは、国際的にも影響力が強かったよ</p></blockquote>",
  "415": "<h2>415</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">米ソの行き詰まりと「新冷戦」</u></p></blockquote>\n<p>考え方は、同時期の<strong class=\"source-bold\">アメリカのレーガンと同じ新自由主義</strong>だね。</p>\n<p>そして「大国としての<ruby>威信<rt>いしん</rt></ruby>」を示したのが、<strong class=\"source-bold\">フォークランド戦争</strong>だよ。1982年、イギリスとアルゼンチンが領有権を争っていたフォークランド諸島 <strong class=\"source-bold\">【</strong>マルビナス諸島<strong class=\"source-bold\">】</strong>を<strong class=\"source-bold\">アルゼンチン</strong>の親米ガルチェリ軍事政権が<ruby>占領<rt>せんりょう</rt></ruby>すると、サッチャーは「国家の<ruby>名誉<rt>めいよ</rt></ruby>をかけて戦う！」と表明、<strong class=\"source-bold\">アメリカのレーガン大統領にも支持を表明させる</strong>と、空母2隻を含む大軍を派遣した。このフォークランド戦争では、イギリス軍は最新兵器を使用してアルゼンチンと戦い、また国連<ruby>安保理<rt>あんぽり</rt></ruby>でもアルゼンチンに撤退を求める決議を<ruby>採択<rt>さいたく</rt></ruby>させ、50日にわたる戦闘によって、<strong class=\"source-bold\">フォークランド諸島を<ruby>奪還<rt>だっかん</rt></ruby></strong>したんだ。この戦争で、サッチャーの人気は不動のものとなった。</p>\n<p>さらに、<strong class=\"source-bold\">IRA【アイルランド共和国軍】</strong>のテロに対しても強い態度で<ruby>臨<rt>のぞ</rt></ruby>む一方、<strong class=\"source-bold\">北アイルランド協定</strong>を結んで、<strong class=\"source-bold\">英領北アイルランドの行政にアイルランド共和国の参加を認めて</strong>、アイルランド問題の解決に一歩前進したよ。また、対外的には<strong class=\"source-bold\"><ruby>香港<rt>ホンコン</rt></ruby>返還協定</strong>を結び、1997年に<strong class=\"source-bold\">香港の主権を中華人民共和国に返還</strong>することが決まった。ただ、政権の末期にはサッチャーの強権的すぎる政治への批判も高まったよ。そりゃ「鉄の女」だもんね。</p>\n<p>フランスでは、1981年に<strong class=\"source-bold\">社会党のミッテラン</strong>が大統領となり、<strong class=\"source-bold\"><ruby>基幹<rt>きかん</rt></ruby>産業の国有化</strong>や<strong class=\"source-bold\">労働者の権利拡大</strong>など社会主義的な政策を進めたんだけど、結局インフレと財政難で挫折したため、首相を保守派から指名して<strong class=\"source-bold\">保革共存政権【コアビタシオン】</strong>をつくった。以後、<strong class=\"source-bold\">大統領が外交と防衛</strong>、<strong class=\"source-bold\">首相が内政</strong>という分業ができて政局が安定、1995年まで続く長期政権になったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連の行き詰まりを打破するため、ゴルバチョフが登場！</strong></span></h4>\n<p>じゃあ、<strong class=\"source-bold\">ソ連</strong>の動きを見ていこう。ソ連は<strong class=\"source-bold\">アフガニスタンへの<ruby>介入<rt>かいにゅう</rt></ruby></strong>を短期で終わらすつもりだったのに、アメリカが支援するイスラーム＝ゲリラの抵抗が激しくなって<strong class=\"source-bold\">泥沼化、財政を圧迫</strong>した。そして、<strong class=\"source-bold\">ブレジネフ</strong>は高齢と病気でほとんど何もできないまま、<strong class=\"source-bold\">1982年に死去</strong>した……。しかも、ブレジネフがあまりにも長く権力を握っていたから、次の世代もすでに高齢だよ……。あとを継いだアンドロポフは腎臓病で、何もできないまま死去。その後継者チェルネンコもすでに73歳でしかも病気、これまた何もできず死去した。外から見てると「この国はどうなってるんだよ！」ってツッコミ入れたくなるけど、それはソ連のなかでも同じことだ。こうして、<strong class=\"source-bold\">改革を主張する若手が台頭</strong>し始めた。</p>\n<p>1985年、若手の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ</strong></span>が<strong class=\"source-bold\">書記長</strong>に就任し、ソ連は一気に世代交代した。ゴルバチョフは、「<strong class=\"source-bold\">今の状態のソ連で西側に対抗するのは不可能</strong>だ」と感じていた。だってソ連では、1980年代に入っても、農場も工場もほとんどが<ruby>鎌<rt>かま</rt></ruby>やハンマ</p>\n<blockquote><p>ゴルバチョフの登場で、世界は一気に激動の時代に突入するんだ！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "416": "<h2>416</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>ーの手作業……。こんな状態だから、経済成長率もほとんどゼロだ。こりゃ、経済が停滞するのは当たり前だよ。</p>\n<p>そこでゴルバチョフは「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペレストロイカ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">改革</strong></span>】</strong>」を始めたんだ。とはいっても、ペレストロイカは具体的に「これをやろう！」っていうのがあったわけじゃない。とにかく、<strong class=\"source-bold\">政治・経済・文化・社会</strong>……ソ連の全部を<strong class=\"source-bold\">「何か変えないといけない」</strong>ってことだよ。そして、「ペレストロイカ」を進める重要な柱は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グラスノスチ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">情報公開</strong></span>】</strong>」と「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新思考外交</strong></span>」だ。</p>\n<p>「グラスノスチ」とは、<strong class=\"source-bold\">民主化の土台になる大胆な情報公開や言論の自由化、検閲の廃止</strong>などの改革のことだよ。これまでソ連は、国内にも国外にも秘密主義だったからね。ただ、ゴルバチョフを一気にグラスノスチに向かわせたきっかけは、1986年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェルノブイリ原子力発電所事故</strong></span>だ（<strong class=\"source-bold\">現在のウクライナ</strong>で起きたこの事故は、福島第一原発の事故が起きる前には「史上最悪の原発事故」といわれていた）。当時、放射線を観測した北欧諸国が「原発事故が起きてるんじゃないか？」と報道したにもかかわらず、ソ連が3日後まで事故を認めなかったから、世界中から「何を考えてるんだ」とさんざん批判された。ゴルバチョフは<strong class=\"source-bold\">グラスノスチの重要性と<ruby>核軍縮<rt>かくぐんしゅく</rt></ruby>の必要性</strong>を感じたんだね。こうしてグラスノスチが進み、ブレジネフ時代から<ruby>軟禁<rt>なんきん</rt></ruby>されていた<strong class=\"source-bold\">サハロフ博士が解放</strong>されて、モスクワに戻ってきた。この時ゴルバチョフは「同意できない意見でも、発言の場を与えるのが原則である」とコメントしたよ。これまでのソ連じゃ考えられないね！。</p>\n<p>もう一方の「新思考外交」は、<ruby>冷戦<rt>れいせん</rt></ruby>に基づく<strong class=\"source-bold\">西側との対決路線や社会主義国への締めつけをやめる</strong>ってことだ。まず1985年には、いきなりアメリカ大統領レーガンとの<strong class=\"source-bold\">米ソ首脳会議</strong>をおこなった。これを<strong class=\"source-bold\"><ruby>仲介<rt>ちゅうかい</rt></ruby>したのが英首相のサッチャー</strong>だ。サッチャーは、書記長になる前のゴルバチョフと会っているんだけど、その時に「これまでのソ連の指導者とは違って、きちんと交渉できる相手だ」と確信して、レーガンに「ゴルバチョフと会談しなさーい」って説得したんだって！ そして、この米ソ首脳会談で話し合われたのは、ズバリ核軍縮！ ゴルバチョフは「ソ連の経済再建のためには<strong class=\"source-bold\">軍事費の削減が必要</strong>で、しかもアメリカの戦略防衛構想に対抗するのは、<strong class=\"source-bold\">ソ連の経済力と技術力では無理</strong>だ」と思っていたし、レーガンも「<strong class=\"source-bold\"><ruby>双子<rt>ふたご</rt></ruby>の赤字</strong>で、これまでのような<strong class=\"source-bold\"><ruby>軍拡<rt>ぐんかく</rt></ruby>路線は不可能</strong>だ」と思っていたから、お互いに歩み寄ったってわけ。そして、1986年におこなわれた再度の首脳会談を経て、1987年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中距離核戦力全廃条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">INF全廃条約</strong></span>】</strong>を<ruby>締結<rt>ていけつ</rt></ruby>したよ。もちろん、中距離核ミサイルだけだから、全体から見れば数は少ないけど（核弾頭総数の約8%）、<strong class=\"source-bold\">史上初めて核兵器の削減に合意</strong>した意味は大きいよ。そして、ゴルバチョフの「新思考外交」は、彼自身が考えていなかったくらい大きな変化を引き起こすんだ！。</p>",
  "417": "<h2>417</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の終結とソ連の崩壊</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">4</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">冷戦の終結とソ連の崩壊</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">冷戦の終結［1988〜91］</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>〈西側（資本主義）陣営〉</td><td>〈東側（共産主義）陣営〉</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーガン</strong></span>大統領［任1981〜89］</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ</strong></span>書記長［任1985〜91］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">新ベオグラード宣言</strong>［1988］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガニスタン撤退完了</strong></span>［1989］<br>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧革命</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧の社会主義圏消滅</strong></span>）<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>東独：<strong class=\"source-bold\">ホネカー退陣</strong><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンの<ruby>壁<rt>かべ</rt></ruby></strong></span>」<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">開放</strong></span></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>米：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">父</strong></span>）大統領［任1989〜93］<br><span data-source-color=\"green\" style=\"color:#315837\">⬇</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦終結</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルタ会談</strong></span>）［1989］</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span>ソ連：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ大統領</strong></span>就任［1990］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国独立宣言</strong></span>［1990］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>ソ連軍が介入<br><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東西ドイツ統一</strong></span>［1990］</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">湾岸戦争</strong></span>［1991］</td><td><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコン解消</strong></span>［1991］<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構解体</strong></span>［1991］</td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">STARTⅠ</strong></span>［1991］</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td></td><td><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保守派クーデタ</strong></span> <span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党解散</strong></span><br>※<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独立国家共同体</strong></span>創設［1991］<br><span data-source-color=\"red\" style=\"color:#e52715\">⬇</span><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連消滅</strong></span>［1991.12］</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「新思考外交」が、東欧革命と冷戦終結をもたらした！</strong></span></h4>\n<p>ゴルバチョフの「新思考外交」は、資本主義国との間だけではなく、<strong class=\"source-bold\">社会主義国にも大きな変化</strong>を引き起こしたよ。1988年になると、ユーゴスラヴィアの<strong class=\"source-bold\">ベオグラード</strong>を訪問したゴルバチョフは、かつてブレジネフが打ち出した<strong class=\"source-bold\">制限主権論の<ruby>放<rt>ほう</rt></ruby><ruby>棄<rt>き</rt></ruby></strong>、簡単に言うと、「もうソ連の言うとおりに動かなくてもいいですよ」と宣言した。この<strong class=\"source-bold\">新ベオグラード宣言</strong>を聞いた東欧諸国は、「そんなこと言って、どうせ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "418": "<h2>418</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>ソ連に反抗すると、また軍隊がくるんでしょ……」って思っていた。でも、ゴルバチョフの改革は止まらなかったんだ。</p>\n<p>1989年になると、ソ連国内では、初めて複数の候補者が立候補して“競争”する人民代議員選挙がおこなわれ、共産党幹部が多数落選するなか、モスクワでは<strong class=\"source-bold\">急進改革派のエリツィンが圧勝</strong>した。さらに<strong class=\"source-bold\">中国を訪問</strong>して<ruby>鄧小平<rt>とうしょうへい</rt></ruby>と会談し、<strong class=\"source-bold\">中ソ論争を終わらせた</strong>。そして、東欧諸国を一気に民主化に向かわせたのは、前年に約束していたとおりに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連軍がアフガニスタンから撤退</strong></span>したことだった。「アフガニスタンがソ連から自由になったなら、今度こそ自分たちもソ連から自由になれる」と思った東欧諸国で一気に民主化が進み、共産党支配が崩壊していった。いわゆる「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東欧革命</strong></span>」の始まりだ！</p>\n<p>まず、<strong class=\"source-bold\">ハンガリーで複数政党制が導入</strong>された。これに続いたのが<strong class=\"source-bold\">ポーランド</strong>だ。すでに1980年には、共産党（＝政府）の指導を受けずに自分たちのことは自分たちで決める！という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自主管理労組</strong></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">「<ruby>連帯<rt>れんたい</rt></ruby>」</strong></span>を結成して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワレサ</strong></span>を議長に、全国で自由化を求めるストライキをやっていた。でも<strong class=\"source-bold\">「連帯」は非合法</strong>とされて、<ruby>弾圧<rt>だんあつ</rt></ruby>を受けながら10年間も民主化を求める運動を続けてきたんだ。</p>\n<p>1989年6月に<strong class=\"source-bold\">初の自由選挙</strong>がおこなわれると、合法となった<strong class=\"source-bold\">「連帯」が圧勝</strong>して<strong class=\"source-bold\">共産党の一党<ruby>独裁<rt>どくさい</rt></ruby>体制が崩壊</strong>した（翌年、<strong class=\"source-bold\">ワレサが大統領になった</strong>！）。この時ソ連は<ruby>介入<rt>かいにゅう</rt></ruby>しなかった。さらに9月、民主化が進んだ<strong class=\"source-bold\">ハンガリーがオーストリアとの国境の開放</strong>を発表すると、東ドイツ市民はハンガリーとオーストリアを経由して、次々と西ドイツに<ruby>亡命<rt>ぼうめい</rt></ruby>し始めたよ。</p>\n<p>東欧の民主化の波は、もう止められない！ <strong class=\"source-bold\">東ドイツ</strong>国内でも市民のデモが日に日に激化し、10月には、18年間も独裁権を握ってきた<strong class=\"source-bold\">ホネカー書記長が退陣</strong>した。それでも市民のデモは全く収まらず、東ベルリンのデモは100万人になった！ もはや国民を抑えきれないと判断した東ドイツ政府は、ついに「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリンの<ruby>壁<rt>かべ</rt></ruby></strong></span>」を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">開放</strong></span>！ 東ベルリン市民が西ベルリンに流れ込んだよ。このニュースはあっという間に世界に伝わり、東ベルリン市民と西ベルリン市民が抱き合って喜ぶ姿や、壁によじ登ってハンマーやつるはしで「壁」を壊す市民の姿が、テレビを通じて全世界に流された。この時、僕は高校生で、「世界が変わってる！」って興奮したのを今でも覚えているよ。そして、この興奮が残る1990年8月、冷戦の<ruby>象徴<rt>しょうちょう</rt></ruby>だった分断国家、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東西ドイツが統一</strong></span>を実現した（<strong class=\"source-bold\">東西ドイツ統一条約</strong>）。ただ、統一後の国名は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ連邦共和国</strong></span>、つまり<strong class=\"source-bold\">西ドイツが東ドイツを吸収</strong>する形で統一を実現したんだね。首都は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン</strong></span>、首相は<strong class=\"source-bold\">西ドイツ首相</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コール</strong></span>だ。</p>\n<p>さらに、隣国<strong class=\"source-bold\">チェコスロヴァキアでもフサーク政権が崩壊</strong>して、かつて「プラハの春」を指導した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドプチェク</strong></span>が復活！ 1989年12月にはハヴェルを大統領、ドプチェ</p>\n<blockquote><p>ソ連が介入しないとわかれば、もはや止めるものは何もないよ</p></blockquote>",
  "419": "<h2>419</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の終結とソ連の崩壊</u></p></blockquote>\n<h4><strong class=\"source-bold\">〈冷戦終結とソ連の崩壊〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td><strong class=\"source-bold\">アイルランド</strong></td><td><strong class=\"source-bold\">イギリス</strong></td><td><strong class=\"source-bold\">ノルウェー</strong></td><td><strong class=\"source-bold\">フィンランド</strong></td></tr><tr><td><strong class=\"source-bold\">オランダ</strong></td><td><strong class=\"source-bold\">デンマーク</strong></td><td><strong class=\"source-bold\">スウェーデン</strong></td><td><strong class=\"source-bold\">エストニア</strong></td></tr><tr><td><strong class=\"source-bold\">ベルギー</strong></td><td><strong class=\"source-bold\">東ドイツ</strong></td><td><strong class=\"source-bold\">ポーランド</strong></td><td><strong class=\"source-bold\">ラトヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">フランス</strong></td><td><strong class=\"source-bold\">西ドイツ</strong></td><td><strong class=\"source-bold\">チェコスロヴァキア</strong></td><td><strong class=\"source-bold\">リトアニア</strong></td></tr><tr><td><strong class=\"source-bold\">ポルトガル</strong></td><td><strong class=\"source-bold\">スイス</strong></td><td><strong class=\"source-bold\">オーストリア</strong></td><td><strong class=\"source-bold\">ベラルーシ</strong></td></tr><tr><td><strong class=\"source-bold\">スペイン</strong></td><td><strong class=\"source-bold\">イタリア</strong></td><td><strong class=\"source-bold\">ハンガリー</strong></td><td><strong class=\"source-bold\">ウクライナ</strong></td></tr><tr><td><strong class=\"source-bold\">ユーゴスラヴィア</strong></td><td><strong class=\"source-bold\">アルバニア</strong></td><td><strong class=\"source-bold\">ルーマニア</strong></td><td><strong class=\"source-bold\">モルドバ</strong></td></tr><tr><td><strong class=\"source-bold\">ギリシア</strong></td><td><strong class=\"source-bold\">トルコ</strong></td><td><strong class=\"source-bold\">ブルガリア</strong></td><td><strong class=\"source-bold\">ソ連→ロシア連邦</strong></td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td><strong class=\"source-bold\">グルジア</strong></td><td><strong class=\"source-bold\">アルメニア</strong></td><td><strong class=\"source-bold\">アゼルバイジャン</strong></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">マルタ会談［1989.12］</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"hatch\" data-source-pattern=\"vertical-lines\" style=\"color:#e52715\">▥</span></td><td>1989年に体制が崩壊した東欧の社会主義国</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"area\" style=\"color:#e52715\">■</span></td><td>ソ連崩壊後のロシア連邦</td></tr><tr><td><span data-source-color=\"brown\" data-source-marker=\"hatch\" data-source-pattern=\"horizontal-lines\" style=\"color:#a43725\">▤</span></td><td>ソ連から独立した国</td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\">━</span></td><td>統一後のドイツ</td></tr></tbody></table></div>\n<p>クを連邦議会議長とする新政権ができた（武力や暴力を使わずに“なめらかに”進んだから<strong class=\"source-bold\">「ビロード革命」</strong>という）。そして、独自路線だった<strong class=\"source-bold\">ルーマニア</strong>では独裁者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チャウシェスクが処刑</strong></span>され、この映像までもがテレビで全世界に流されたんだ。</p>\n<p>もはや、<strong class=\"source-bold\">東欧の共産圏はすべてなくなった</strong>！ こうして1989年末に地中海の<strong class=\"source-bold\">マルタ島</strong>でおこなわれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米ソ首脳会談</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルタ会談</strong></span>）で、レーガンのあとにアメリカ大統領となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">父</strong></span>）とソ連の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフ</strong></span>は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>冷戦<rt>れいせん</rt></ruby>終結</strong></span>を宣言したんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連内部にも東欧革命の影響が広がり、体制の改革を迫られた！</strong></span></h4>\n<p>1989年、東欧諸国で次々と共産党の一党独裁政権が倒れると、<strong class=\"source-bold\">ソ連国内でも民主化を求める動きが起こった。</strong>だって、これまで東ヨーロッパの民主化を<ruby>潰<rt>つぶ</rt></ruby>してきたソ連が、今回は動かなかったんだもん。そして、ソ連共産党の一党独裁体制に対する批判が高まり、1990年、ゴルバチョフはソ連が<strong class=\"source-bold\">複数政党制を導入</strong>することを決め、同時に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大統領制</strong></span>を導入したんだ。もちろん、<strong class=\"source-bold\">初代のソ連大統領がゴルバチョフ</strong>だ。これは、<strong class=\"source-bold\">ソ連という「国」と共産党という「党」</strong>を切り離して、支配の中心を<strong class=\"source-bold\">「党から国家へ」</strong>と変えたということなんだけど、実はこの改革自体がソ連を崩壊させるものだと、この時には誰も気づいていなかった。もちろん、ゴルバチョフ本人も含めてね。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "420": "<h2>420</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p>ここでちょっとだけ、<strong class=\"source-bold\">ソ連という国の体制</strong>について解説するよ。ソ連が成立した時の話を少し思い出してみよう！ ソ連は全部で<strong class=\"source-bold\">15の共和国</strong>からできていて、それぞれの国に共産党があり、<strong class=\"source-bold\">各国の共産党は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党</strong></span>に完全に支配されている。</strong>これは、共産党しか政党がない一党<ruby>独裁<rt>どくさい</rt></ruby>国家だから可能な体制だよ。じゃあ<strong class=\"source-bold\">複数政党</strong>を認めて<strong class=\"source-bold\">大統領制</strong>を導入するとどうなるんだろ？ 共産党は共産党しか支配できないから、ほかの政党ができちゃうと、<strong class=\"source-bold\">共産党だけが各共和国を支配する根拠がなくなる</strong>んだよ。だからゴルバチョフは「ソ連政府」を共産党から分離して、大統領をつくったんだけど、じゃあ<strong class=\"source-bold\">「ソ連大統領」はどこを支配するの？</strong> ハッキリ言って、このへんがあいまいだった。だから、<strong class=\"source-bold\">「連邦制」</strong>をめぐる議論が起きたんだ。どういうことかというと、ソ連が<strong class=\"source-bold\">連邦制国家（1つの国）</strong>なのか、<strong class=\"source-bold\">国家連合（今のEUのような複数の国の連合体）</strong>なのかってことね。ソ連の国名は英語だと「Union of Soviet Socialist Republics」。この「Union」の意味が問題になったんだよ。</p>\n<h4><strong class=\"source-bold\">〈もともとのソ連の体制のイメージ〉</strong></h4>\n<blockquote><p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党</strong></span><br><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連政府</strong></span></span></span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党が共産党を通じて各国を支配</strong></span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-color=\"black\" data-source-marker=\"outline-arrow\" style=\"color:#001000\">⇙</span></td><td><span data-source-color=\"black\" data-source-marker=\"outline-arrow\" style=\"color:#001000\">↓</span></td><td><span data-source-color=\"black\" data-source-marker=\"outline-arrow\" style=\"color:#001000\">⇘</span></td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"dashed\" style=\"border:1px dashed #001000;padding:0 0.2em\"><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span><br><strong class=\"source-bold\">各共和国</strong></span></td><td><span data-source-border=\"black\" data-source-border-style=\"dashed\" style=\"border:1px dashed #001000;padding:0 0.2em\"><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span><br><strong class=\"source-bold\">各共和国</strong></span></td><td><span data-source-border=\"black\" data-source-border-style=\"dashed\" style=\"border:1px dashed #001000;padding:0 0.2em\"><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span><br><strong class=\"source-bold\">各共和国</strong></span></td></tr></tbody></table></div>\n<blockquote><p>もともとの体制は、ソ連が共産党の一党独裁だから可能なんだよ</p></blockquote>\n<h4><strong class=\"source-bold\">〈1990年後半のソ連のイメージ〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" style=\"border:1px solid #315837;padding:0 0.2em\"><strong class=\"source-bold\">ソ連大統領</strong></span></td><td><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党</strong></span></span></td></tr><tr><td><strong class=\"source-bold\">ソ連大統領が支配するところは？</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">この体制でソ連共産党は必要なの？</strong></span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア政府</strong></span><br><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">他の政党</strong></span></span></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ウクライナ</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ウクライナ政府</strong></span><br><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">他の政党</strong></span></span></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">各共和国</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">共和国政府</strong></span><br><span data-source-border=\"red\" data-source-border-style=\"dotted\" style=\"border:1px dotted #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党</strong></span></span> <span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">他の政党</strong></span></span></td></tr></tbody></table></div>\n<blockquote><p>ロシアに「ロシア大統領」ができたら、ソ連はどこを支配するの？</p></blockquote>",
  "421": "<h2>421</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">冷戦の終結とソ連の崩壊</u></p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ バルト3国が独立を宣言！ 各共和国にも自立の動きが広がる</strong></span></h4>\n<p>こんな議論で<ruby>揉<rt>も</rt></ruby>めているうちに、「東欧諸国がソ連から自由になったように、自分たちも“ソ連”から独立する！」と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国</strong></span>（<strong class=\"source-bold\">エストニア・ラトヴィア・リトアニア</strong>）が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独立宣言</strong></span>を出したよ。これにはさすがのゴルバチョフも<strong class=\"source-bold\">「ソ連軍」を派遣して<ruby>弾圧<rt>だんあつ</rt></ruby></strong>した！。しかし、今度は世界的に「民主化弾圧だ！」と批判されてしまった。さらにこの動きは各国にも影響し、各共和国で「主権宣言（ソ連のなかに残るけど、独自の政府をつくる）」を出す動きが広がると、ロシアでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エリツィン</strong></span>が<strong class=\"source-bold\">ロシア大統領</strong>になった。ちょっと待った！ <strong class=\"source-bold\">ソ連の領土の大半がロシア</strong>だよね。ロシアが主権宣言を出したら、ソ連を残す必要はあるのかな？ こうしてソ連の内部では、ソ連政府と各共和国政府の間で激しい対立が起こり、さらに<strong class=\"source-bold\">ソ連の体制を維持しようとする共産党の保守派</strong>は、巻き返しを狙っていたんだ。</p>\n<p>一方で、<ruby>冷戦<rt>れいせん</rt></ruby>の終結を受けて<strong class=\"source-bold\">社会主義陣営</strong>（共産圏）<strong class=\"source-bold\">の解体</strong>が一気に進んだよ。1991年6月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コメコンが解消</strong></span>され、7月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワルシャワ条約機構が解体</strong></span>された。もう東欧に社会主義国が残っていないから、なくなって当然だよね。さらに、米ソの<ruby>核軍縮<rt>かくぐんしゅく</rt></ruby>も進んだ。7月には米大統領<strong class=\"source-bold\">ブッシュとゴルバチョフ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次戦略兵器削減条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>START<rt>スタート</rt></ruby>Ⅰ</strong></span>】</strong>に調印して、米ソ両国が核<ruby>弾頭<rt>だんとう</rt></ruby>やミサイルの削減に合意した。しかし、こうした動きのウラでソ連は確実に解体へと向かっていたんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 保守派クーデタ、ソ連共産党の解散、そしてついにソ連が崩壊！</strong></span></h4>\n<p>冷戦体制を支えてきた<strong class=\"source-bold\">共産圏の解体や核軍縮</strong>によって、アメリカがどんどん優位に立つのを見て、保守派は我慢できなかった。しかも、<strong class=\"source-bold\">ゴルバチョフは<ruby>市場<rt>しじょう</rt></ruby>経済への移行を唱え始め</strong>、さらにソ連を主権共和国の連合体とする<strong class=\"source-bold\">新連邦条約を提案</strong>すると、保守派は「<strong class=\"source-bold\">この条約ができた瞬間、ソ連が崩壊する</strong>」と気づき、ついに<strong class=\"source-bold\">クーデタを決行</strong>したんだ。</p>\n<p>1991年8月、ロシアのテレビで「<strong class=\"source-bold\">ゴルバチョフは病気で大統領を続けられない</strong>ので、ヤナーエフ副大統領が職務を引き継ぐ」というニュースが流れ、さらに改革派の活動を禁止する「非常事態宣言」が発表された！。世界中に衝撃が走った！ これは、どう考えてもクーデタだ！ しかし、進み始めた歴史は止められない。ロシア大統領の<strong class=\"source-bold\">エリツィン</strong>は「<strong class=\"source-bold\">連邦よりもロシアだ！ クーデタに抵抗せよ！</strong>」と市民や軍に呼びかけた。これは「<strong class=\"source-bold\">もうソ連は必要ない！</strong>」ってことだ。戦車によじ登り、ハンドマイクで市民に呼びかけるエリツィンの姿に市民も立ち上がり、ついにクーデタに反対する市民のデモは10万人以上になった。こうして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保守派クーデタ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反ゴルバチョフ＝クーデタ</strong></span>】</strong>は失敗に終わったんだ。</p>\n<p>「ロシア」大統領のエリツィンがクーデタを失敗に追い込んだことで、<strong class=\"source-bold\">ゴルバチョフに対するエリツィ</strong></p>\n<blockquote><p>保守派クーデタの失敗を機に、エリツィンとゴルバチョフの立場が逆転したんだ！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "422": "<h2>422</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第22回</strong></span> 冷戦の展開③（1970〜1991）</p></blockquote>\n<p><strong class=\"source-bold\">ンの優位</strong>が決まった。これはそのまま<strong class=\"source-bold\">ソ連よりもロシアが優位に立った</strong>瞬間だ。エリツィンが「ロシアでは共産党の活動を停止する」という命令を出すと、ゴルバチョフはこれに従うしかなく、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党の解散</strong></span>が宣言された。さらに、ロシアが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルト3国の独立</strong></span>を認める」と発表したから、ソ連もこれを承認するしかない。もはや、各共和国のソ連からの「独立」は止められなくなった。そして12月には、<strong class=\"source-bold\">ロシア・ウクライナ・ベラルーシ</strong>の3国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独立国家共同体</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">CIS</strong></span>】</strong>の発足を宣言すると<strong class=\"source-bold\">旧ソ連の11共和国</strong>が参加した（グルジア <strong class=\"source-bold\">【</strong>ジョージア<strong class=\"source-bold\">】</strong>の参加は1993年）。こうなると<strong class=\"source-bold\">ソ連大統領の存在する意味は全くない</strong>。事態を悟ったゴルバチョフは、1991年12月25日に<strong class=\"source-bold\">ソ連大統領を辞任</strong>し、完全に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連が消滅</strong></span>したんだ。</p>\n<h4><strong class=\"source-bold\">〈ソ連崩壊のイメージ〉</strong></h4>\n<blockquote><p><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"text-decoration:line-through;text-decoration-color:#001000\"><span data-source-border=\"green\" data-source-border-style=\"solid\" style=\"border:1px solid #315837;padding:0 0.2em\"><strong class=\"source-bold\">ソ連大統領</strong></span></span>　<strong class=\"source-bold\">ゴルバチョフの辞任＝ソ連の消滅</strong></p></blockquote>\n<blockquote><p><span data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;padding:0 0.2em\"><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">独立国家共同体</strong></span></span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア政府</strong></span></span></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ウクライナ</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ウクライナ政府</strong></span></span></td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ベラルーシ</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ベラルーシ政府</strong></span></span></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">各共和国</strong><br><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">共和国政府</strong></span></span></td></tr></tbody></table></div>\n<blockquote><p>各共和国が独立しちゃうと、ソ連には大統領のゴルバチョフ「ただ1人」しか残らないね</p></blockquote>\n<p>じゃあ、今回はこれでおしまい。最後に年号 check！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">!!</span> <span data-source-color=\"red\" data-source-background=\"white\" style=\"color:#e52715;background-color:#ffffff\">年号</span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">のツボ</span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">ドル＝ショック</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1971</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span>ら<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>泣<rt>7</rt></ruby><ruby>い<rt>1</rt></ruby></strong></span>ても　ドル下がる）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">第4次中東戦争（第1次石油危機）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1973</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>港<rt>3</rt></ruby></strong></span>に　石油ない）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">ソ連のアフガニスタン<ruby>侵攻<rt>しんこう</rt></ruby></strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1979</strong></span>］</td><td>（アフガンに　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>救<rt>9</rt></ruby></strong></span>援　ソ連がきたぞ）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">ゴルバチョフ登場（書記長就任）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1985</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>や<rt>8</rt></ruby><ruby>ゴ<rt>5</rt></ruby></strong></span>ルビー　ペレストロイカ）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\"><ruby>冷戦<rt>れいせん</rt></ruby>終結（マルタ会談）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1989</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>特<rt>19</rt></ruby><ruby>約<rt>89</rt></ruby></strong></span>つけて　冷戦終結）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">東西ドイツ統一</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1990</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一つ<rt>1</rt></ruby></strong></span>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>く<rt>9</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>れ<rt>0</rt></ruby></strong></span>　東西ドイツ）</td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\">●</span><strong class=\"source-bold\">ソ連の消滅</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1991</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ひ<rt>1</rt></ruby><ruby>ど<rt>9</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>悔<rt>1</rt></ruby>い</strong></span>ても　ソ連は消えた）</td></tr></tbody></table></div>\n<p>ついにソ連もなくなっちゃった。残った重要テーマは<strong class=\"source-bold\">アジア・アフリカ</strong>だけだ。冷戦終結後は最後にまとめてやるからね。</p>",
  "423": "<h2>423</h2>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">9</strong></span></h3>\n<h4><strong class=\"source-bold\">〜バブル経済と55年体制の崩壊〜</strong></h4>\n<p>オイル＝ショックの影響で、日本でも<strong class=\"source-bold\">「狂乱物価」と呼ばれる物価高騰</strong>が起きて、トイレットペーパーの買い占めなどの心理的パニックも起きたよ。そして、<strong class=\"source-bold\">1974年には戦後初めて経済成長率がマイナスになった</strong>。でも、これをきっかけに<strong class=\"source-bold\">省エネ技術の開発や産業の高度化で</strong>、なんとか危機を克服したんだ。そして、先進国の経済が停滞するなかで、規制の緩和などで自由競争を促し、政府の<ruby>介入<rt>かいにゅう</rt></ruby>を極力減らして「<strong class=\"source-bold\">小さな政府</strong>」を目指す<strong class=\"source-bold\">新自由主義</strong>の政策が台頭してきた。日本でも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>中曽根康弘<rt>なかそねやすひろ</rt></ruby></strong></span>政権の時代に、<strong class=\"source-bold\">日本国有鉄道</strong>（国鉄・現在のJR各社）や<strong class=\"source-bold\">日本電信電話公社</strong>（現在のNTT）などの<strong class=\"source-bold\">民営化</strong>が進んだよ。</p>\n<p>1980年代の日本は、<strong class=\"source-bold\">自動車などの輸出を急速に増やして経済成長</strong>していたんだけど、反面で対米貿易黒字が拡大して<strong class=\"source-bold\">日米貿易<ruby>摩擦<rt>まさつ</rt></ruby></strong>が激化し、アメリカから<ruby>市場<rt>しじょう</rt></ruby>開放を迫られて、例えば<strong class=\"source-bold\">牛肉やオレンジの輸入自由化</strong>なんかをおこなったんだ。1985年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プラザ合意</strong></span>で<strong class=\"source-bold\">急速な円高が進んで輸出産業が打撃</strong>を受けると（<strong class=\"source-bold\">円高<ruby>不況<rt>ふきょう</rt></ruby></strong>）、その対策として<strong class=\"source-bold\">内需拡大</strong>（輸出より国内での需要をふやす）<strong class=\"source-bold\">のための<ruby>金融緩和<rt>きんゆうかんわ</rt></ruby></strong>をしたんだけど、お金が借りやすくなって余った資金や、アメリカの景気後退を受けた外国からの資金が<strong class=\"source-bold\">土地や株などの投機的な取引</strong>に向かった結果、<strong class=\"source-bold\">地価や株価の異常高騰</strong>で「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バブル経済</strong></span>」になったんだ！。</p>\n<p>しかし、1990年初めから<strong class=\"source-bold\">株価や地価が下落</strong>し始め（<strong class=\"source-bold\">バブル崩壊</strong>）、日本では長期の不況が始まった。同じころ、<strong class=\"source-bold\">違法な政治献金の問題で自民党への批判が高まり</strong>（リクルート事件）、1993年には自民党が分裂して総選挙で過半数を割り込み、<strong class=\"source-bold\">共産党を除く非自民8党派</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>細川護熙<rt>ほそかわもりひろ</rt></ruby></strong></span>内閣が成立、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">55年体制が崩壊</strong></span>したんだ。そして、衆議院の選挙制度が<strong class=\"source-bold\">小選挙区比例代表並立制</strong>となった。</p>\n<p>自民党は社会党党首の<strong class=\"source-bold\"><ruby>村山富市<rt>むらやまとみいち</rt></ruby></strong>を首相とする連立内閣で政権に復帰したんだけど、革新系の野党第1党と組むなんて、ちょっと変だよね。その後も自民党を中心とする政権が続き、2001年に公明党との連立で成立した<strong class=\"source-bold\"><ruby>小泉純一郎<rt>こいずみじゅんいちろう</rt></ruby></strong>内閣は、<strong class=\"source-bold\">新自由主義</strong>政策をとり、財政赤字の削減と景気回復のために、<strong class=\"source-bold\">大胆な民営化と規制緩和</strong>を進めたよ。<strong class=\"source-bold\">郵政事業の民営化</strong>や<strong class=\"source-bold\">日本道路公団の分割と民営化</strong>、<strong class=\"source-bold\">社会保障費の見直し</strong>などをおこなったんだけど、<strong class=\"source-bold\"><ruby>雇用<rt>こよう</rt></ruby>の流動化</strong>が進んで<strong class=\"source-bold\">所得格差</strong>が拡大するなど、現代の日本に繋がる問題も発生し始めたんだよ。</p>\n<p>そして、小泉首相の退任後は<strong class=\"source-bold\">自民党政治への不信感が高まり</strong>、2009年の総選挙では<strong class=\"source-bold\">野党の民主党が勝利</strong>して、<strong class=\"source-bold\"><ruby>鳩山由紀夫<rt>はとやまゆきお</rt></ruby></strong>を首相とする連立内閣ができた。しかし民主党政権は、党内の混乱や2011年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東日本大震災</strong></span><strong class=\"source-bold\">への対応の不手際</strong>などで支持を失い、2012年には<strong class=\"source-bold\">自民党政権に戻った</strong>んだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>"
};

